        assert_eq!(parse_copy("all"), Some(CopyRequest::All));
        assert_eq!(parse_copy("code"), Some(CopyRequest::Code(None)));
        assert_eq!(parse_copy("code 2"), Some(CopyRequest::Code(Some(2))));
